check "ledger-writer has a native sidecar log-shipper (init container, restartPolicy Always) sharing the log volume" bash -c "[ \"\$(kubectl --context main -n audit get deploy ledger-writer -o jsonpath='{.spec.template.spec.initContainers[?(@.name==\"log-shipper\")].restartPolicy} {.spec.template.spec.initContainers[?(@.name==\"log-shipper\")].volumeMounts[0].name}')\" = 'Always logs' ]"
check "ledger-writer is rolled out and log-shipper's stdout contains the application log" bash -c "deploy_ready main ledger-writer audit 1 && kubectl --context main -n audit logs deploy/ledger-writer -c log-shipper --tail=-1 | grep -q 'E-1042 checksum mismatch'"
check "errors.txt holds exactly the three ERROR lines" bash -c "f='$ANSWERS/errors.txt'; [ -f \"\$f\" ] && [ \$(grep -c . \"\$f\") -eq 3 ] && grep -q 'ERROR E-1042' \"\$f\" && grep -q 'ERROR E-2210' \"\$f\" && grep -q 'ERROR E-3007' \"\$f\""
check "hungry-container.txt names the container using most CPU" file_eq "$ANSWERS/hungry-container.txt" transcoder
